// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/", wrapper.Index)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/home", wrapper.HandleHome)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/home/feeds", wrapper.HandleShowFeeds)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/home/feeds/mark/{mark}", wrapper.MarkFeeds)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/home/items", wrapper.HandleShowItems)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/home/items/mark/{mark}", wrapper.MarkItems)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/home/{feed}/{item}", wrapper.HandleUnsaveItem)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/home/{feed}/{item}", wrapper.HandleShowItem)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/home/{feed}/{item}", wrapper.HandleSaveItem)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/home/{feed}/{item}/{mark}", wrapper.MarkItem)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/login/{provider}", wrapper.Login)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/login/{provider}/callback", wrapper.LoginCallback)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/logout", wrapper.Logout)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/search", wrapper.Search)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/settings", wrapper.GetSettings)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/settings/theme", wrapper.GetTheme)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/settings/theme", wrapper.SetTheme)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/signup", wrapper.SignUp)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/signup", wrapper.ProcessSignUp)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/subscription/add", wrapper.AddSubscription)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/subscription/edit/{subscription}", wrapper.EditSubscription)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/subscription/edit/{subscription}", wrapper.SaveSubscription)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/subscription/import", wrapper.StartImport)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/subscription/import", wrapper.ProcessImport)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/subscription/import", wrapper.SetImportMethod)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/subscription/mark/{mark}/{subscription}", wrapper.MarkSubscription)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/subscription/new", wrapper.NewSubscription)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/subscription/remove/{subscription}", wrapper.RemoveSubscription)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/subscriptions/mark/{mark}", wrapper.MarkAllSubscriptions)
	})

	return r
}
